arguments.command:
python3 -c "
# Parse the GMT file to find immune-relevant pathways
pathways = {}
with open('/workspace/ReactomePathways.gmt') as f:
    for line in f:
        parts = line.strip().split('\t')
        name = parts[0]
        pathway_id = parts[1]
        genes = parts[2:]
        pathways[name] = {'id': pathway_id, 'genes': genes}

print(f'Total pathways: {len(pathways)}')

# Find immune-relevant pathways - those with 'immune' or 'immun' in name
immune_keywords = ['immune', 'immun', 'T cell', 'T-cell', 'B cell', 'B-cell', 'cytokine', 'interferon', 'interleukin', 'antigen', 'MHC', 'HLA', 'NK cell', 'natural killer', 'complement', 'adaptive', 'innate', 'inflam', 'chemokine', 'TCR', 'BCR', 'CD', 'PD-1', 'PD1', 'CTLA', 'FOXP3', 'regulatory T', 'Th1', 'Th2', 'Th17', 'IL-', 'IFN', 'granzyme', 'perforin', 'cytotoxic', 'activation', 'costimul']

immune_pathways = {}
for name, info in pathways.items():
    name_lower = name.lower()
    for kw in immune_keywords:
        if kw.lower() in name_lower:
            immune_pathways[name] = info
            break

print(f'Immune-relevant pathways: {len(immune_pathways)}')
for name in sorted(immune_pathways.keys())[:30]:
    print(f'  {name} ({len(immune_pathways[name][\"genes\"])} genes)')
"

